using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// RSGD DNAM was a raw 560-byte "Floats" array. It is xEdit's Generation Data: a Biome and a Cell set, each with
// seven tiers (Common, Uncommon, Rare, Exotic, Unique, Special, Everywhere) of ten floats. The test reads a whole
// record from Starfield.esm with both readers and writes it back byte for byte.
public class ResourceGenerationDataTests
{
    // CrateredNoLifeDefaultRes (0083E0:Starfield.esm): Iron, Aluminum and Helium-3
    private const string Cratered = "";

    [Fact]
    public void GenerationData_Decoded()
    {
        var bytes = Record("RSGD", Hex(Cratered));
        foreach (var rsgd in ReadBoth<IResourceGenerationDataGetter>(bytes,
                     f => ResourceGenerationData.CreateFromBinary(f),
                     (s, p) => ResourceGenerationDataBinaryOverlay.ResourceGenerationDataFactory(s, p)))
        {
            rsgd.EditorID.ShouldBe("CrateredNoLifeDefaultRes");
            rsgd.Items.Count.ShouldBe(3);

            // ResInorgCommonIron (0057C7:Starfield.esm)
            var iron = rsgd.Items[0];
            iron.Resource.FormKey.ID.ShouldBe(0x0057C7u);
            var common = iron.GenerationData.Biome.Common;
            common.VeinNodesMin.ShouldBe(1f);
            common.VeinNodesMax.ShouldBe(11f);
            common.NodeSizeMin.ShouldBe(11f);
            common.NodeSizeMax.ShouldBe(22f);
            common.Unknown1.ShouldBe(0f);
            common.MaxAngleOffset.ShouldBe(45f);
            common.ChanceToAppear.ShouldBe(30f);
            iron.GenerationData.Biome.Exotic.ChancePerNode.ShouldBe(10f);
            iron.GenerationData.Biome.Exotic.MaxNodeOffset.ShouldBe(45f);
            iron.GenerationData.Biome.Unique.VeinNodesMax.ShouldBe(0f);
            var cell = iron.GenerationData.Cell.Common;
            cell.VeinNodesMin.ShouldBe(1f);
            cell.VeinNodesMax.ShouldBe(5f);
            cell.NodeSizeMin.ShouldBe(22f);
            cell.NodeSizeMax.ShouldBe(33f);
            cell.SegmentLengthMin.ShouldBe(33f);
            cell.SegmentLengthMax.ShouldBe(44f);
            cell.MaxAngleOffset.ShouldBe(45f);
            cell.ChanceToAppear.ShouldBe(60f);
            cell.SurfaceItemChanceNone.ShouldBe(5f);
            cell.Blobbiness.ShouldBe(0f);
            iron.GenerationData.Cell.Exotic.ChanceToAppear.ShouldBe(15f);

            // ResInorgCommonAluminum (0057D6:Starfield.esm): the Unique tiers are used
            var aluminum = rsgd.Items[1];
            aluminum.Resource.FormKey.ID.ShouldBe(0x0057D6u);
            aluminum.GenerationData.Biome.Unique.VeinNodesMax.ShouldBe(11f);
            aluminum.GenerationData.Cell.Unique.NodeSizeMin.ShouldBe(55f);
            aluminum.GenerationData.Cell.Unique.NodeSizeMax.ShouldBe(111f);
            aluminum.GenerationData.Cell.Unique.SegmentLengthMax.ShouldBe(155f);

            // ResInorgCommonHelium3_G (0057F5:Starfield.esm): only the Special tiers
            var helium = rsgd.Items[2];
            helium.Resource.FormKey.ID.ShouldBe(0x0057F5u);
            helium.GenerationData.Biome.Common.ChanceToAppear.ShouldBe(0f);
            helium.GenerationData.Biome.Special.ChancePerNode.ShouldBe(100f);
            helium.GenerationData.Cell.Special.ChanceToAppear.ShouldBe(25f);
            helium.GenerationData.Cell.Special.SurfaceItemChanceNone.ShouldBe(100f);
            helium.GenerationData.Cell.Everywhere.VeinNodesMax.ShouldBe(0f);

            var written = GameConstants.Starfield.MajorRecord(Write(w => rsgd.WriteToBinary(w)));
            written.Content.ToArray().ShouldBe(Hex(Cratered));
        }
    }
}
